CREATE TYPE "public"."model_pricing_operation" AS ENUM('chat_input', 'chat_output', 'chat_cached_input', 'embedding', 'rerank');--> statement-breakpoint
CREATE TYPE "public"."model_pricing_unit" AS ENUM('per_million_tokens', 'per_request', 'per_1k_tokens');--> statement-breakpoint
CREATE TABLE "model_pricing" (
	"id" text PRIMARY KEY NOT NULL,
	"provider" text NOT NULL,
	"model" text NOT NULL,
	"operation" "model_pricing_operation" NOT NULL,
	"price_micros_per_unit" bigint NOT NULL,
	"unit" "model_pricing_unit" NOT NULL,
	"effective_from" timestamp with time zone NOT NULL,
	"effective_to" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
CREATE INDEX "model_pricing_lookup_idx" ON "model_pricing" USING btree ("provider","model","operation","effective_from");
